import{_ as e,o as l,c as n,a2 as t}from"./chunks/framework.ClgMjOt7.js";const y=JSON.parse('{"title":"PallaSync 同期エンジン仕様","description":"設定暗号化、データ同期プロトコル、コンフリクト解決アルゴリズム","frontmatter":{"title":"PallaSync 同期エンジン仕様","description":"設定暗号化、データ同期プロトコル、コンフリクト解決アルゴリズム"},"headers":[],"relativePath":"dev/pallasync-engine.md","filePath":"dev/pallasync-engine.md","lastUpdated":1789105872000}'),o={name:"dev/pallasync-engine.md"};function r(c,a,s,i,d,p){return l(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="pallasync-同期エンジン仕様" tabindex="-1">PallaSync 同期エンジン仕様 <a class="header-anchor" href="#pallasync-同期エンジン仕様" aria-label="Permalink to &quot;PallaSync 同期エンジン仕様&quot;">​</a></h1><p><code>pallasync</code> パッケージは、設定データおよび状態を端末間で安全に保護・同期するためのカスタム同期サブシステムです。</p><hr><h2 id="主要クラス構成" tabindex="-1">主要クラス構成 <a class="header-anchor" href="#主要クラス構成" aria-label="Permalink to &quot;主要クラス構成&quot;">​</a></h2><ul><li><strong><code>PalleriaSyncManager</code></strong>: 同期処理の全体ライフサイクルを管轄。</li><li><strong><code>PallaSyncKeystore</code></strong>: <code>AndroidKeyStore</code> 内で生成した 256 ビット AES 鍵を用い、データの暗号化（AES-256-GCM / NoPadding）および改ざん検証タグ付与を実施。</li><li><strong><code>PallaSyncConflictResolver</code></strong>: タイムスタンプに基づく LWW (Last-Write-Wins) アルゴリズムで最終変更優先の競合解決を実行。</li><li><strong><code>PallaSyncEventApplier</code></strong>: 解決されたイベントをローカル DataStore および Room DB に同期適用。</li></ul>',5)])])}const S=e(o,[["render",r]]);export{y as __pageData,S as default};
